# Historical initial wiring receipt; not a final-state replay script. Native performance gate later withheld the UI option.
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
def edit(name,changes):
 p=ROOT/name;raw=p.read_bytes();crlf=b'\r\n' in raw;s=raw.decode('utf-8').replace('\r\n','\n')
 for old,new in changes:
  if old not in s: raise RuntimeError(f'{name}: missing {old[:90]}')
  s=s.replace(old,new,1)
 p.write_bytes(s.replace('\n','\r\n' if crlf else '\n').encode('utf-8'))
